import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"官方资料与链接","description":"","frontmatter":{},"headers":[],"relativePath":"cookbook/resources.md","filePath":"cookbook/resources.md","lastUpdated":null}'),l={name:"cookbook/resources.md"};function i(s,t,n,h,d,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="官方资料与链接" tabindex="-1">官方资料与链接 <a class="header-anchor" href="#官方资料与链接" aria-label="Permalink to &quot;官方资料与链接&quot;">​</a></h1><p>继续学习的权威资源。</p><h2 id="nts-官方" tabindex="-1">NTS 官方 <a class="header-anchor" href="#nts-官方" aria-label="Permalink to &quot;NTS 官方&quot;">​</a></h2><ul><li><strong>GitHub 仓库</strong>：<a href="https://github.com/NetTopologySuite/NetTopologySuite" target="_blank" rel="noreferrer">NetTopologySuite/NetTopologySuite</a></li><li><strong>官方文档</strong>：<a href="https://nettopologysuite.github.io/NetTopologySuite/api/NetTopologySuite.html" target="_blank" rel="noreferrer">nettopologysuite.github.io/NetTopologySuite</a></li><li><strong>NuGet 包</strong>：<a href="https://www.nuget.org/packages/NetTopologySuite" target="_blank" rel="noreferrer">NetTopologySuite</a></li><li><strong>Issue 列表</strong>：<a href="https://github.com/NetTopologySuite/NetTopologySuite/issues" target="_blank" rel="noreferrer">github.com/NetTopologySuite/NetTopologySuite/issues</a></li></ul><h2 id="关联项目" tabindex="-1">关联项目 <a class="header-anchor" href="#关联项目" aria-label="Permalink to &quot;关联项目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://github.com/NetTopologySuite/ProjNet4GeoAPI" target="_blank" rel="noreferrer">ProjNet</a></td><td>坐标系转换 (CRS)</td></tr><tr><td><a href="https://www.nuget.org/packages/NetTopologySuite.IO.GeoJSON" target="_blank" rel="noreferrer">NetTopologySuite.IO.GeoJSON</a></td><td>GeoJSON 序列化</td></tr><tr><td><a href="https://www.nuget.org/packages/NetTopologySuite.IO.PostGis" target="_blank" rel="noreferrer">NetTopologySuite.IO.PostGis</a></td><td>PostGIS 二进制格式</td></tr><tr><td><a href="https://www.nuget.org/packages/NetTopologySuite.Features" target="_blank" rel="noreferrer">NetTopologySuite.Features</a></td><td>Feature / FeatureCollection 抽象</td></tr></tbody></table><h2 id="上游与同源项目" tabindex="-1">上游与同源项目 <a class="header-anchor" href="#上游与同源项目" aria-label="Permalink to &quot;上游与同源项目&quot;">​</a></h2><ul><li><strong>JTS Topology Suite</strong>（Java 原版）：<a href="https://github.com/locationtech/jts" target="_blank" rel="noreferrer">locationtech/jts</a><ul><li>NTS 算法与 JTS 1:1 对应，JTS 文档对 NTS 也适用</li></ul></li><li><strong>GEOS</strong>（C/C++ 移植）：<a href="https://github.com/libgeos/geos" target="_blank" rel="noreferrer">libgeos/geos</a><ul><li>PostGIS 内部使用 GEOS</li></ul></li></ul><h2 id="数据库空间扩展文档" tabindex="-1">数据库空间扩展文档 <a class="header-anchor" href="#数据库空间扩展文档" aria-label="Permalink to &quot;数据库空间扩展文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据库</th><th>文档</th></tr></thead><tbody><tr><td>PostgreSQL + PostGIS</td><td><a href="https://postgis.net/documentation/" target="_blank" rel="noreferrer">postgis.net/documentation</a></td></tr><tr><td>SQL Server Spatial</td><td><a href="https://learn.microsoft.com/sql/relational-databases/spatial/spatial-data-types-overview" target="_blank" rel="noreferrer">Spatial Data Types</a></td></tr><tr><td>SQLite + SpatiaLite</td><td><a href="https://www.gaia-gis.it/gaia-sins/" target="_blank" rel="noreferrer">gaia-gis.it/gaia-sins</a></td></tr><tr><td>MySQL Spatial</td><td><a href="https://dev.mysql.com/doc/refman/8.0/en/spatial-types.html" target="_blank" rel="noreferrer">Spatial Data Types</a></td></tr></tbody></table><h2 id="ef-core-空间数据" tabindex="-1">EF Core 空间数据 <a class="header-anchor" href="#ef-core-空间数据" aria-label="Permalink to &quot;EF Core 空间数据&quot;">​</a></h2><ul><li><strong>EF Core 空间数据官方文档</strong>：<a href="https://learn.microsoft.com/ef/core/modeling/spatial" target="_blank" rel="noreferrer">learn.microsoft.com/ef/core/modeling/spatial</a></li><li><strong>Npgsql 文档</strong>：<a href="https://www.npgsql.org/efcore/mapping/nts.html" target="_blank" rel="noreferrer">npgsql.org/efcore/mapping/nts.html</a></li></ul><h2 id="ogc-标准" tabindex="-1">OGC 标准 <a class="header-anchor" href="#ogc-标准" aria-label="Permalink to &quot;OGC 标准&quot;">​</a></h2><ul><li><strong>Simple Features Access for SQL</strong>：<a href="https://www.ogc.org/standards/sfa" target="_blank" rel="noreferrer">OGC 06-104r4</a>（NTS 实现的核心规范）</li><li><strong>DE-9IM</strong>：Wikipedia 上的 <a href="https://en.wikipedia.org/wiki/DE-9IM" target="_blank" rel="noreferrer">DE-9IM</a> 解释非常清楚</li></ul><h2 id="必读论文与文章" tabindex="-1">必读论文与文章 <a class="header-anchor" href="#必读论文与文章" aria-label="Permalink to &quot;必读论文与文章&quot;">​</a></h2><ol><li><strong>&quot;JTS Topology Suite: A Geometry Package for Java&quot;</strong> —— JTS 的设计哲学</li><li><strong>&quot;Geometric Algorithms for Spatial Data&quot;</strong> —— NTS 涉及的核心算法综述</li><li><strong>PostGIS in Action</strong>（书）—— 大量内容直接适用于 NTS</li><li><strong>PostGIS Documentation: Chapter 5 &quot;Spatial Queries&quot;</strong> —— SQL 空间查询的圣经</li></ol><h2 id="经典教程与博客" tabindex="-1">经典教程与博客 <a class="header-anchor" href="#经典教程与博客" aria-label="Permalink to &quot;经典教程与博客&quot;">​</a></h2><ul><li><a href="https://lin-ear-th-inking.blogspot.com/" target="_blank" rel="noreferrer">Planet JTS</a> —— JTS 作者 Martin Davis 的博客，深入解释算法</li><li><a href="https://www.postgis.us/" target="_blank" rel="noreferrer">Planet PostGIS</a> —— Regina Obe &amp; Leo Hsu 的 PostGIS 实战博客</li><li><a href="https://workshops.boundlessgeo.com/postgis-intro/" target="_blank" rel="noreferrer">Boundless PostGIS Tutorial</a> —— 经典 PostGIS 教程</li></ul><h2 id="算法可视化" tabindex="-1">算法可视化 <a class="header-anchor" href="#算法可视化" aria-label="Permalink to &quot;算法可视化&quot;">​</a></h2><ul><li><a href="https://cartesiancafe.com/voronoi-diagram-delaunay-triangulation/" target="_blank" rel="noreferrer">Voronoi Diagram 可视化</a> —— Voronoi 与 Delaunay 的图解</li><li><a href="https://gis.stackexchange.com/questions/145/what-is-de-9im" target="_blank" rel="noreferrer">DE-9IM Matrix 交互演示</a> —— 矩阵的视觉化解释</li></ul><h2 id="坐标参考系资源" tabindex="-1">坐标参考系资源 <a class="header-anchor" href="#坐标参考系资源" aria-label="Permalink to &quot;坐标参考系资源&quot;">​</a></h2><ul><li><strong>EPSG Registry</strong>：<a href="https://epsg.org/" target="_blank" rel="noreferrer">epsg.org</a> —— 全球坐标系数据库</li><li><strong>EPSG.io</strong>：<a href="https://epsg.io/" target="_blank" rel="noreferrer">epsg.io</a> —— 友好的 EPSG 查询界面</li><li><strong>Spatial Reference</strong>：<a href="https://spatialreference.org/" target="_blank" rel="noreferrer">spatialreference.org</a> —— WKT 格式查询</li></ul><h2 id="国内坐标系" tabindex="-1">国内坐标系 <a class="header-anchor" href="#国内坐标系" aria-label="Permalink to &quot;国内坐标系&quot;">​</a></h2><p>中国常用坐标系：</p><table tabindex="0"><thead><tr><th>SRID</th><th>名称</th><th>用途</th></tr></thead><tbody><tr><td>4326</td><td>WGS84</td><td>GPS、Google Maps</td></tr><tr><td>4490</td><td>CGCS2000</td><td>中国国家大地坐标系</td></tr><tr><td>4480</td><td>CGCS2000 (3D)</td><td>大地测量</td></tr><tr><td>3857</td><td>Web 墨卡托</td><td>Web 地图（米制）</td></tr><tr><td>4527</td><td>CGCS2000 / 3 度带 / 中央经线 114°</td><td>中国 1:1 万测图</td></tr><tr><td>4499</td><td>CGCS2000 / Gauss-Kruger CM 117E</td><td>中国高斯投影</td></tr></tbody></table><p>国内坐标转换注意事项：</p><ul><li>WGS84 ↔ GCJ-02（火星坐标）：需要 <strong>非公开</strong> 的偏移算法，NTS 不内置</li><li>GCJ-02 ↔ BD-09：百度地图坐标系</li><li>高精度坐标转换用 CGCS2000 框架</li></ul><h2 id="推荐学习路径" tabindex="-1">推荐学习路径 <a class="header-anchor" href="#推荐学习路径" aria-label="Permalink to &quot;推荐学习路径&quot;">​</a></h2><h3 id="入门-1-周" tabindex="-1">入门（1 周） <a class="header-anchor" href="#入门-1-周" aria-label="Permalink to &quot;入门（1 周）&quot;">​</a></h3><ol><li>本教程的 <a href="./../guide/introduction">入门</a> → <a href="./../guide/getting-started">快速开始</a> → <a href="./../guide/first-geometry">第一个几何</a></li><li><a href="./../core/geometry-hierarchy">几何层级</a> → <a href="./../core/wkt-wkb">WKT/WKB</a></li><li>跑通 <a href="./cheatsheet">API 速查表</a> 中的模板</li></ol><h3 id="进阶-2-3-周" tabindex="-1">进阶（2~3 周） <a class="header-anchor" href="#进阶-2-3-周" aria-label="Permalink to &quot;进阶（2~3 周）&quot;">​</a></h3><ol><li><a href="./../operations/overlay">几何操作</a> → <a href="./../operations/buffer">缓冲区</a></li><li><a href="./../predicates/relationships">空间谓词</a> → <a href="./../predicates/de9im">DE-9IM</a></li><li><a href="./../advanced/prepared-geometry">PreparedGeometry</a> → <a href="./../advanced/spatial-index">空间索引</a></li><li><a href="./../integration/ef-core">EF Core 集成</a></li></ol><h3 id="实战-项目驱动" tabindex="-1">实战（项目驱动） <a class="header-anchor" href="#实战-项目驱动" aria-label="Permalink to &quot;实战（项目驱动）&quot;">​</a></h3><ol><li>选一个真实场景（如&quot;附近的人&quot;、配送范围、轨迹分析）</li><li>把数据库 + EF Core + NTS + Web API 全部串起来</li><li>遇到性能问题回到本教程的 <a href="./../advanced/prepared-geometry">进阶主题</a> 章节</li></ol><h2 id="反馈与社区" tabindex="-1">反馈与社区 <a class="header-anchor" href="#反馈与社区" aria-label="Permalink to &quot;反馈与社区&quot;">​</a></h2><ul><li><strong>本教程改进</strong>：在 GitHub 仓库提 PR 或 Issue</li><li><strong>NTS bug 报告</strong>：<a href="https://github.com/NetTopologySuite/NetTopologySuite/issues" target="_blank" rel="noreferrer">NetTopologySuite Issues</a></li><li><strong>中文 GIS 社区</strong>：osgeo.cn、CSDN GIS 板块</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./cheatsheet">API 速查表</a></li><li><a href="./faq">常见问题 FAQ</a></li><li>回到 <a href="./../">首页</a></li></ul>',38)])])}const c=e(l,[["render",i]]);export{p as __pageData,c as default};
